import CoreData

// `Professor` itself is generated by Xcode from the `Professor` entity in
// EduAccess.xcdatamodeld (codeGenerationType="class"), so this file only
// adds Swift-friendly convenience on top of the generated NSManagedObject
// subclass — it does not declare the class.

extension Professor {
    /// Typed wrapper around the raw `statusRaw` Core Data attribute.
    var status: AvailabilityStatus {
        get { AvailabilityStatus(rawValue: statusRaw ?? "") ?? .unavailable }
        set { statusRaw = newValue.rawValue }
    }
}
